import{_ as n,c as t,o as i,a3 as r}from"./chunks/framework.CoV49S2T.js";const p=JSON.parse('{"title":"Anpassung","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/customize.md","filePath":"de/guide/customize.md","lastUpdated":1787284674000}'),a={name:"de/guide/customize.md"};function s(l,e,o,d,u,g){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="anpassung" tabindex="-1">Anpassung <a class="header-anchor" href="#anpassung" aria-label="Permalink to &quot;Anpassung&quot;">​</a></h1><p>Machen Sie ClipboxAI so, wie Sie arbeiten. Dieser Leitfaden behandelt die Einstellungen, die Sie anpassen können.</p><h2 id="allgemein" tabindex="-1">Allgemein <a class="header-anchor" href="#allgemein" aria-label="Permalink to &quot;Allgemein&quot;">​</a></h2><p>Öffnen Sie <strong>ClipboxAI → Einstellungen</strong> (oder drücken Sie <code>Cmd+,</code>).</p><ul><li><strong>Language</strong>: Englisch, 简体中文, 繁體中文, 日本語.</li><li><strong>Launch at Login</strong>: startet die App automatisch bei der Anmeldung.</li><li><strong>Appearance</strong>: Hell, Dunkel oder System (folgt macOS).</li></ul><h2 id="ki-konfiguration" tabindex="-1">KI-Konfiguration <a class="header-anchor" href="#ki-konfiguration" aria-label="Permalink to &quot;KI-Konfiguration&quot;">​</a></h2><p>Richten Sie Cloud-KI unter <strong>Einstellungen → KI</strong> ein:</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Optionen</th><th>Beschreibung</th></tr></thead><tbody><tr><td><strong>Provider</strong></td><td>DeepSeek, MiniMax, GLM, Kimi, Mistral, Ollama, OpenAI, Anthropic, Gemini</td><td>Der aufzurufende OpenAI-kompatible Dienst</td></tr><tr><td><strong>API Key</strong></td><td>Ihr Schlüssel</td><td>Im <strong>Keychain</strong> gespeichert, niemals im Klartext auf die Festplatte geschrieben</td></tr><tr><td><strong>Model</strong></td><td>pro Anbieter</td><td>Das für KI-Aktionen verwendete Modell</td></tr><tr><td><strong>Cloud AI enabled</strong></td><td>Ein / Aus</td><td>Hauptschalter zum Senden von Einträgen in die Cloud</td></tr></tbody></table><p>Cloud-KI ist <strong>standardmäßig deaktiviert</strong>. Wenn aktiviert, wird Ihr Eintrag nur an den von Ihnen konfigurierten Anbieter gesendet.</p><h2 id="aktionen" tabindex="-1">Aktionen <a class="header-anchor" href="#aktionen" aria-label="Permalink to &quot;Aktionen&quot;">​</a></h2><p>Passen Sie das Verhalten der Werkzeuge an:</p><ul><li><strong>Auto-run on output</strong>: Wenn aktiviert, läuft das ausgewählte Werkzeug automatisch in dem Moment, in dem Sie kopieren.</li><li><strong>Excluded apps</strong>: Hier aufgeführte Apps werden von der Zwischenablagen-Überwachung und Auto-run übersprungen (z. B. Passwort-Manager).</li><li><strong>Tool order</strong>: Ziehen Sie im KI-Werkzeug-Fenster installierte Werkzeuge, um sie neu anzuordnen; Ihre Reihenfolge wird gemerkt.</li></ul><h2 id="datenschutz" tabindex="-1">Datenschutz <a class="header-anchor" href="#datenschutz" aria-label="Permalink to &quot;Datenschutz&quot;">​</a></h2><p>Öffnen Sie <strong>Einstellungen → Privacy</strong>:</p><ul><li><strong>Cloud AI opt-in</strong>: Der Hauptschalter zum Senden von Daten an einen Anbieter.</li><li><strong>Excluded apps</strong>: Stoppt die Erfassung bestimmter Apps.</li><li><strong>History controls</strong>: Verwaltet, wie lange Einträge auf Ihrem Gerät aufbewahrt werden.</li></ul><p>Der gesamte Verlauf bleibt lokal. Wir laden Einträge nicht hoch und führen keine Analysen durch.</p><h2 id="marketplace" tabindex="-1">Marketplace <a class="header-anchor" href="#marketplace" aria-label="Permalink to &quot;Marketplace&quot;">​</a></h2><p>Verwalten Sie installierte Aktionen:</p><ul><li><strong>Browse</strong>: Öffnen Sie den <strong>Marketplace</strong> aus dem KI-Werkzeug-Fenster oder der Website.</li><li><strong>Install</strong>: Klicken Sie bei einer Aktion auf <strong>Install</strong>, um sie über Deep-Link hinzuzufügen.</li><li><strong>Remove</strong>: Deinstallieren Sie eine Aktion aus Ihrer Liste <strong>Installed</strong>.</li></ul><h2 id="menuleiste" tabindex="-1">Menüleiste <a class="header-anchor" href="#menuleiste" aria-label="Permalink to &quot;Menüleiste&quot;">​</a></h2><ul><li><strong>Show in menu bar</strong>: Symbol in der Menüleiste aktivieren/deaktivieren.</li><li><strong>Quit on close</strong>: Wählen Sie, ob die App im Hintergrund weiterläuft.</li></ul><h2 id="tipps" tabindex="-1">Tipps <a class="header-anchor" href="#tipps" aria-label="Permalink to &quot;Tipps&quot;">​</a></h2><ul><li>Halten Sie Cloud-KI deaktiviert, bis Sie sie benötigen — lokale Werkzeuge decken die meiste tägliche Bereinigung ab.</li><li>Fügen Sie Passwort-Manager und sichere Eingabe-Apps zu <strong>Excluded apps</strong> hinzu, damit Geheimnisse nie erfasst werden.</li><li>Kombinieren Sie Auto-run mit einem lokalen Werkzeug für die griffbereite Textbereinigung bei jedem Kopiervorgang.</li></ul>',23)])])}const c=n(a,[["render",s]]);export{p as __pageData,c as default};
